and an isPermaLink guid.

   Dates are RFC 822 per the RSS spec, not RFC 3339. Tera autoescapes .xml
   templates, so bare `{{ }}` is safe and only pre-escaped URLs need `| safe`. -#}


     {{ config.title }}{%- if term %} — #{{ term.name }}{%- endif %}

       {%- if term -%}
         {{ term.permalink | escape_xml | safe }}
       {%- elif section -%}
         {{ section.permalink | escape_xml | safe }}
       {%- else -%}
         {{ config.base_url | escape_xml | safe }}
       {%- endif -%}

     {{ config.description }}
     Zola
     {{ lang }}
     {%- if config.extra.author_email %}
     {{ config.extra.author_email }} ({{ config.author }})
     {{ config.extra.author_email }} ({{ config.author }})
     {%- endif %}

     {% if last_updated is defined %}{{ last_updated | date(format="%a, %d %b %Y %H:%M:%S %z") }}{% endif %}
     {%- if config.extra.og_image %}

       {{ config.base_url ~ config.extra.og_image | escape_xml | safe }}
       {{ config.title }}
       {{ config.base_url | escape_xml | safe }}

     {%- endif %}
     {%- for page in pages %}


         {{ page.title }}
         {{ page.date | date(format="%a, %d %b %Y %H:%M:%S %z") }}
         {% if config.extra.author_email %}{{ config.extra.author_email }} ({% if page.authors %}{{ page.authors[0] }}{% else %}{{ config.author }}{% endif %}){% else %}{% if page.authors %}{{ page.authors[0] }}{% else %}{{ config.author }}{% endif %}{% endif %}
         {{ page.permalink | escape_xml | safe }}
         {{ page.permalink | escape_xml | safe }}
         {%- for tag in page.taxonomies.tags | default(value=[]) %}
         {{ tag }}
         {%- endfor %}
         {% if page.summary %}{{ page.summary }}{% else %}{{ page.content }}{% endif %}

     {%- endfor %}
